WITH Ranked_Mkt AS (SELECT idx_info.INDX_SNAME, idx_info.INDX_CODE, idx_info.INNER_CODE, mkt.TRADEDATE, mkt.LCLOSE, mkt.TCLOSE, ROW_NUMBER() OVER(PARTITION BY idx_info.INNER_CODE ORDER BY mkt.TRADEDATE ASC) AS rn_asc, ROW_NUMBER() OVER(PARTITION BY idx_info.INNER_CODE ORDER BY mkt.TRADEDATE DESC) AS rn_desc FROM GET_INDX_GEN_INFO idx_info INNER JOIN INDX_MKT mkt ON idx_info.INNER_CODE = mkt.INNER_CODE WHERE (idx_info.INDX_CODE = '000016' OR idx_info.INDX_SNAME LIKE '%中证白酒%' OR idx_info.INDX_SNAME LIKE '%中证医疗%') AND mkt.TRADEDATE >= '2026-01-01' AND mkt.TRADEDATE <= '2026-09-02' AND idx_info.USE_STATUS = '使用' AND idx_info.ISVALID = 1 AND mkt.ISVALID = 1) SELECT t_start.INDX_SNAME AS `指数名称`, t_start.INDX_CODE AS `指数代码`, DATE_FORMAT(t_start.TRADEDATE, '%Y-%m-%d') AS `起算日期`, t_start.LCLOSE AS `期初昨收`, DATE_FORMAT(t_end.TRADEDATE, '%Y-%m-%d') AS `截止日期`, t_end.TCLOSE AS `期末收盘价`, ROUND((t_end.TCLOSE / t_start.LCLOSE - 1) * 100, 2) AS `今年以来涨跌幅(%)` FROM (SELECT * FROM Ranked_Mkt WHERE rn_asc = 1) t_start INNER JOIN (SELECT * FROM Ranked_Mkt WHERE rn_desc = 1) t_end ON t_start.INNER_CODE = t_end.INNER_CODE WHERE t_start.LCLOSE IS NOT NULL AND t_start.LCLOSE > 0 AND t_end.TCLOSE IS NOT NULL ORDER BY `今年以来涨跌幅(%)` DESC;
